const axios = require("axios");

async function requestOcr(imageUrl) {
  try {
    const response = await axios.post(
      "https://ocr.ac/action",
      {
        url: imageUrl
      },
      {
        headers: {
          "Content-Type": "application/json"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

// Contoh penggunaan, ganti dengan URL gambar yang sebenarnya
const imageUrlToProcess = "https://example.com/path/to/your/image.jpg"; // Ganti dengan URL gambar yang valid

requestOcr(imageUrlToProcess)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
